// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 contractBal, uint256 extraDeal) public {
        vm.assume(contractBal >= 1);
        vm.assume(contractBal <= address(this).balance);
        address recipient = address(0xbeef);
        uint256 preRecipientBal = recipient.balance;
        uint256 preContractBal = contractBal;
        vm.deal(address(c), contractBal);
        c.withdrawAll(recipient);
        uint256 postRecipientBal = recipient.balance;
        assertTrue(postRecipientBal - preRecipientBal == preContractBal);
    }
}
